package io.github.long0823.tclbondriver;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class IptvCoreTest {
 static int crc(byte[] b,int at,int len){int v=-1;for(int i=at;i<at+len;i++){v^=(b[i]&255)<<24;for(int j=0;j<8;j++)v=(v&0x80000000)!=0?(v<<1)^0x04c11db7:v<<1;}return v;}
 public static void main(String[] args)throws Exception{String upstream=String.join("",Collections.nCopies(64,"a")),access=String.join("",Collections.nCopies(48,"b"));String ini="[Control]\nToken="+upstream+"\n[Channel0]\nName=Test station\nDisplayNumber=041\nONID=1234\nTSID=1234\nServiceID=101\n";IptvCatalog c=IptvCatalog.parse(ini.getBytes(StandardCharsets.UTF_8));String m3u=c.playlist("http://192.0.2.1:40560",access,1);if(m3u.contains(upstream)||!m3u.contains("/tuner/1/channel/1234-1234-101.ts")||!m3u.startsWith("#EXTM3U\n"))throw new AssertionError("M3U metadata/credential separation");boolean rejected=false;try{c.playlist("http://192.0.2.1",upstream,0);}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("Native key accepted as IPTV key");
 byte[] p=new byte[188];Arrays.fill(p,(byte)255);p[0]=0x47;p[1]=0x40;p[2]=0;p[3]=0x10;p[4]=0;p[5]=0;p[6]=(byte)0xb0;p[7]=17;p[8]=4;p[9]=(byte)210;p[10]=(byte)0xc1;p[11]=0;p[12]=0;p[13]=0;p[14]=101;p[15]=(byte)0xe1;p[16]=0;p[17]=0;p[18]=102;p[19]=(byte)0xe2;p[20]=0;int checksum=crc(p,5,16);for(int i=0;i<4;i++)p[21+i]=(byte)(checksum>>(24-i*8));ByteArrayOutputStream out=new ByteArrayOutputStream();new IptvProgram(1234,101).packet(p,0,out);byte[] selected=out.toByteArray();if(selected.length!=188||selected[7]!=13||selected[14]!=101||crc(selected,5,16)!=0)throw new AssertionError("Single-program PAT / CRC");p[22]^=1;out.reset();new IptvProgram(1234,101).packet(p,0,out);if(out.size()!=0)throw new AssertionError("Bad PAT CRC accepted");System.out.println("PASS: IPTV-only credential, M3U, selected PAT and CRC validation");
 if(args.length==4){byte[] source=Files.readAllBytes(Paths.get(args[0]));IptvProgram program=new IptvProgram(Integer.parseInt(args[2]),Integer.parseInt(args[3]));try(OutputStream file=Files.newOutputStream(Paths.get(args[1]))){for(int at=0;at+188<=source.length;at+=188){if(source[at]!=0x47)throw new AssertionError("TS alignment");program.packet(source,at,file);}}System.out.println("Real TS selected-program output written (private fixture)");}
 }
}